func (q *Queries) DeleteReleasableLeasedEphemeralWorker(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, deleteReleasableLeasedEphemeralWorker, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const enterEphemeralLease = `-- name: EnterEphemeralLease :execrows
UPDATE workers w
   SET lease_since   = clock_timestamp(),
       lease_repo_id = r.repo_id,
       lease_branch  = fn_run_lease_branch(r.kind, r.branch, r.pipeline_ref, r.issue_iid, r.failure_snapshot),
       updated_at    = now()
  FROM runs r
 WHERE w.id = $1
   AND w.ephemeral
   AND NOT w.isolated_lane
   AND w.ephemeral_run_id = $2::uuid
   AND w.draining_since IS NULL
   AND r.id = $2::uuid
   AND r.worker_id = w.id
   AND r.status IN ('completed', 'failed')
   AND r.repo_id IS NOT NULL
   AND r.egress_profile_id IS NULL
   AND fn_run_lease_branch(r.kind, r.branch, r.pipeline_ref, r.issue_iid, r.failure_snapshot) IS NOT NULL
   AND NOT EXISTS (
       SELECT 1 FROM runs o
       WHERE o.worker_id = w.id
         AND o.status NOT IN ('completed', 'failed', 'cancelled'))
   AND NOT EXISTS (
       SELECT 1 FROM recovery_custody_holds h
       WHERE h.live_worker_id = w.id AND h.state = 'open')
`

type EnterEphemeralLeaseParams struct {
	WorkerID uuid.UUID `json:"worker_id"`
	RunID    uuid.UUID `json:"run_id"`
}

// PRD #2006: start the ephemeral lease on the worker that just served its bound run, in the SAME
// transaction that commits the run's terminal state (the caller holds the worker row lock, taken
// before the run's). lease_since is clock_timestamp(), so the lease starts at the commit-side
// instant, not the transaction-start one. Matches exactly one row, and only when ALL hold:
//   - the worker is ephemeral, outside the isolated lane, not draining, and bound to @run_id;
//   - the run ended completed or failed (never cancelled), was served by THIS worker, is repo-backed, carries no egress profile and
//     has a derivable effective branch identity (fn_run_lease_branch non-NULL) -- the identity the
//     lease stores, so a follow-up must match it (a run with none never leases: fail closed);
//   - the worker holds no other non-terminal run and no OPEN custody hold (the caller releases a
//     completed run's hold earlier in the same transaction, so the check reads that release).
//
// Zero rows means "do not lease": the caller falls back to today's immediate teardown.
func (q *Queries) EnterEphemeralLease(ctx context.Context, arg EnterEphemeralLeaseParams) (int64, error) {
	result, err := q.db.Exec(ctx, enterEphemeralLease, arg.WorkerID, arg.RunID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const expirePendingHostedWorkerTokens = `-- name: ExpirePendingHostedWorkerTokens :execrows
UPDATE hosted_worker_tokens SET token_ciphertext = NULL
WHERE token_ciphertext IS NOT NULL
  AND created_at < $1
`

// Bound how long a sealed join token may sit at rest (PRD #58, a residual BEYOND
// Decision 3's stated one). The documented residual is plaintext in etcd for the
// worker's lifetime; this is different: the pending copy sits in Postgres sealed
// under UZI_SECRET_KEY, the master key the vault (PRD #32) exists to stop relying
// on — per docs/vault-threat-model.md an operator holding the api env plus a DB
// dump has every master-sealed value in plaintext. If the controller never polls
// (chart not deployed, controller down, hosting flipped off after provisioning,
// worker abandoned), "delivered once" would quietly degrade into "at rest
// indefinitely".
//
// Expiring is BENIGN in the normal case, and that is what makes 1h a safe default
// even though the pending window is now pod-scheduling-plus-image-pull rather than
// two poll intervals. This clears the api's sealed BUFFER, not the token: if the
// controller already wrote the Secret, the plaintext is in the cluster and
// workers.token_hash is untouched, so whenever the pod finally boots it reads the
// file, authenticates, registers, and MarkHostedWorkerTokenDelivered corrects the
// row late (its expired-state clause exists for exactly that self-heal).
//
// Expiry only strands when the Secret was NEVER written — which is precisely the
// case the TTL exists for. A stranded worker is visible (it never comes online,
// Decision 10's heartbeat) and recoverable (M2/M3 rotate a new token in via
// UpsertHostedWorkerToken), whereas an unbounded sealed secret is neither.
// delivered_at stays NULL, which is what marks the row stranded rather than done.
//
// So the TTL now means "no pod ever proved it booted", NOT "the controller never
// picked it up".
func (q *Queries) ExpirePendingHostedWorkerTokens(ctx context.Context, cutoff pgtype.Timestamptz) (int64, error) {
	result, err := q.db.Exec(ctx, expirePendingHostedWorkerTokens, cutoff)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const leaseClockNow = `-- name: LeaseClockNow :one
SELECT clock_timestamp()::timestamptz AS at
`

// PRD #2006: a FRESH database instant for lease admission. now() is the transaction-start time, so
// a claim transaction that waited on a lock would judge a lease against a stale instant; the claim
// reads clock_timestamp() through this query IMMEDIATELY before ClaimRun, after every lock and guard
// it waits on, and passes it as ClaimRun's @lease_at.
func (q *Queries) LeaseClockNow(ctx context.Context) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, leaseClockNow)
	var at pgtype.Timestamptz
	err := row.Scan(&at)
	return at, err
}

const listHostedWorkersForController = `-- name: ListHostedWorkersForController :many

SELECT w.id,
       w.template_declared,
       w.hosted_size,
       w.hosted_generation,
       w.docker_enabled,
       -- busy (PRD #422 M3, Decision 5): does this worker hold any non-terminal run? This
       -- reuses the EXACT active-run predicate the DeleteWorker guard uses
       -- (CountWorkerNonTerminalRuns), awaiting_approval included, because rolling a worker
       -- that holds such a run would requeue it. Feeds the controller's cordon/defer-roll
       -- decision (M4).
       (SELECT count(*) FROM runs r
          WHERE r.worker_id = w.id
            AND r.status NOT IN ('completed', 'failed', 'cancelled')) > 0 AS busy,
       -- draining_since (PRD #422 M3/M5): the raw nullable cordon timestamp — WHEN this
       -- worker was cordoned, or NULL if it is not draining (draining == draining_since != nil).
       -- M5 selects the timestamp itself rather than an ` + "`" + `IS NOT NULL` + "`" + ` boolean because the
       -- controller's reconcile loop is stateless (it remembers nothing across ticks) and must
       -- compute ` + "`" + `now - draining_since >= deadline` + "`" + ` to enforce the bounded drain deadline; the
       -- bool it replaces could only answer "draining y/n", not "for how long".
       w.draining_since,
       -- disk_pressure (PRD #837 M4): the ONE lifecycle reader of the display-only disk
       -- telemetry, allow-listed exactly like ReapEphemeralWorkers is for the uptime anchor. It
       -- is a DEBOUNCED, FRESHNESS-GATED derivation, never the raw sample:
       --   * streak >= @disk_pressure_min_streak (2): HeartbeatWorker only increments the
       --     streak on a fresh tick whose sample is over threshold and resets it otherwise,
       --     so >=2 means "the last two consecutive heartbeats both saw pressure" — a single
       --     spike or a transient statfs blip never fires the controller's roll/teardown.
       --   * last_heartbeat_at fresh (IS NOT NULL AND >= @heartbeat_cutoff): a worker that
       --     went silent must not keep asserting pressure off a frozen streak. The cutoff is
       --     the same now()-WORKER_HEARTBEAT_STALE the claim path uses.
       -- Purely "under pressure": ephemeral is selected SEPARATELY below and NOT baked in
       -- here — the controller composes the two. This stays lifecycle-only; a hostile worker
       -- drives its own streak, so this value never reaches claim/scheduling.
       -- COALESCE(...,false)::boolean pins this to a NON-NULL Go bool. The last_heartbeat_at
       -- comparison makes sqlc infer a nullable expression (and COALESCE alone types as
       -- interface{}), but the ` + "`" + `IS NOT NULL` + "`" + ` conjunct means the value is FALSE — never NULL —
       -- for a never-heartbeated worker, so the COALESCE is a typing aid the runtime never
       -- exercises. The explicit ::boolean is what makes sqlc emit ` + "`" + `bool` + "`" + `, so
       -- DesiredWorker.DiskPressure stays a plain bool like Busy.
       COALESCE(w.stats_disk_pressure_streak >= $1::int
        AND w.last_heartbeat_at IS NOT NULL
        AND w.last_heartbeat_at >= $2, false)::boolean AS disk_pressure,
       ARRAY_REMOVE(ARRAY[
         CASE WHEN w.stats_disk_pressure_streak >= 2 AND w.nix_pressure AND w.last_heartbeat_at >= $2 THEN 'nix'::text END,
         CASE WHEN w.stats_disk_pressure_streak >= 2 AND w.data_pressure AND w.last_heartbeat_at >= $2 THEN 'data'::text END,
         CASE WHEN w.dind_pressure_streak >= 2 AND w.dind_meter_at >= now() - interval '45 seconds' THEN 'dind'::text END
       ], NULL)::text[] AS disk_pressure_volumes,
       w.maintenance_id, w.maintenance_nonce, w.maintenance_phase,
       w.maintenance_deployment_uid, w.maintenance_pvc_uid, w.maintenance_register_nonce,
       w.maintenance_fenced, w.maintenance_ready_ack,
       w.ephemeral,
       -- isolated_lane (PRD #1906 M5): the server-set lane marker, mapped to DesiredWorker.Isolated
       -- so the controller renders the worker into the isolated lane's namespace.
       w.isolated_lane,
       -- custody_held (PRD #1296 M4, D3/D9): does this worker hold any OPEN custody hold?
       -- A distinct desired-worker signal, independent of busy/draining_since — a held
       -- worker is NOT free, and both ordinary controller teardown and the data-PVC recycle
       -- paths must honor it (M4b consumes this to keep a custody-held PVC alive). EXISTS is
       -- cast to a NON-NULL Go bool (an uncast EXISTS types as interface{}), mirroring the
       -- disk_pressure column's ::boolean above, so DesiredWorker.CustodyHeld stays a plain
       -- bool like Busy.
       (EXISTS (
           SELECT 1 FROM recovery_custody_holds h
           WHERE h.live_worker_id = w.id AND h.state = 'open'
       ))::boolean AS custody_held,
       t.token_ciphertext
FROM workers w
LEFT JOIN hosted_worker_tokens t ON t.worker_id = w.id
WHERE w.kind = 'hosted'
ORDER BY w.created_at ASC
`

type ListHostedWorkersForControllerParams struct {
	DiskPressureMinStreak int32              `json:"disk_pressure_min_streak"`
	HeartbeatCutoff       pgtype.Timestamptz `json:"heartbeat_cutoff"`
}

type ListHostedWorkersForControllerRow struct {
	ID                       uuid.UUID          `json:"id"`
	TemplateDeclared         pgtype.Text        `json:"template_declared"`
	HostedSize               pgtype.Text        `json:"hosted_size"`
	HostedGeneration         int64              `json:"hosted_generation"`
	DockerEnabled            pgtype.Bool        `json:"docker_enabled"`
	Busy                     bool               `json:"busy"`
	DrainingSince            pgtype.Timestamptz `json:"draining_since"`
	DiskPressure             bool               `json:"disk_pressure"`
	DiskPressureVolumes      []string           `json:"disk_pressure_volumes"`
	MaintenanceID            pgtype.UUID        `json:"maintenance_id"`
	MaintenanceNonce         string             `json:"maintenance_nonce"`
	MaintenancePhase         string             `json:"maintenance_phase"`
	MaintenanceDeploymentUid string             `json:"maintenance_deployment_uid"`
	MaintenancePvcUid        string             `json:"maintenance_pvc_uid"`
	MaintenanceRegisterNonce string             `json:"maintenance_register_nonce"`
	MaintenanceFenced        bool               `json:"maintenance_fenced"`
	MaintenanceReadyAck      bool               `json:"maintenance_ready_ack"`
	Ephemeral                bool               `json:"ephemeral"`
	IsolatedLane             bool               `json:"isolated_lane"`
	CustodyHeld              bool               `json:"custody_held"`
	TokenCiphertext          []byte             `json:"token_ciphertext"`
}

// Hosted workers (PRD #58) --------------------------------------------------
// The controller-facing half of the protocol. Every query here is instance-wide
// (the controller is not a user and reconciles the whole cluster), which is why
// they live apart from runtime.sql's user-scoped worker queries.
// Desired state for the controller's poll: every hosted worker, plus its pending
// sealed join token when one is still awaiting delivery (LEFT JOIN — a worker whose
// pod has already proved it holds its token, or whose token expired unread, returns
// NULL here and is simply reconciled without one).
//
// Deliberately carries NO user-controlled text (Decision 7): workers.name is
// arbitrary 200-byte user input, and the controller renders k8s object names from
// what this hands it. Object naming derives from the uuid (uzi-hw-<id>), so the
// name is not selected here at all, rather than selected and trusted not to be used.
//
// Deliberately unbounded: the whole hosted fleet is the desired state, and the
// controller reconciles it as a set — a paged poll could never express "these are
// all the workers that should exist", which is what makes orphan detection
// (Decision 9) possible. The per-user quota (M2) bounds the row count.
func (q *Queries) ListHostedWorkersForController(ctx context.Context, arg ListHostedWorkersForControllerParams) ([]ListHostedWorkersForControllerRow, error) {
	rows, err := q.db.Query(ctx, listHostedWorkersForController, arg.DiskPressureMinStreak, arg.HeartbeatCutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListHostedWorkersForControllerRow{}
	for rows.Next() {
		var i ListHostedWorkersForControllerRow
		if err := rows.Scan(
			&i.ID,
			&i.TemplateDeclared,
			&i.HostedSize,
			&i.HostedGeneration,
			&i.DockerEnabled,
			&i.Busy,
			&i.DrainingSince,
			&i.DiskPressure,
			&i.DiskPressureVolumes,
			&i.MaintenanceID,
			&i.MaintenanceNonce,
			&i.MaintenancePhase,
			&i.MaintenanceDeploymentUid,
			&i.MaintenancePvcUid,
			&i.MaintenanceRegisterNonce,
			&i.MaintenanceFenced,
			&i.MaintenanceReadyAck,
			&i.Ephemeral,
			&i.IsolatedLane,
			&i.CustodyHeld,
			&i.TokenCiphertext,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockOldestReleasableLeasedEphemeralWorker = `-- name: LockOldestReleasableLeasedEphemeralWorker :one
SELECT w.id
  FROM workers w
 WHERE w.user_id = $1
   AND w.kind = 'hosted'
   AND w.ephemeral
   AND w.lease_since IS NOT NULL
   AND NOT EXISTS (
       SELECT 1 FROM runs r
       WHERE r.worker_id = w.id
         AND r.status NOT IN ('completed', 'failed', 'cancelled'))
   AND NOT EXISTS (
       SELECT 1 FROM recovery_custody_holds h
       WHERE h.live_worker_id = w.id AND h.state = 'open')
 ORDER BY w.lease_since ASC, w.id ASC
 LIMIT 1
   FOR UPDATE OF w SKIP LOCKED
`

// PRD #2006 quota eviction, step 1 of 2 (the provisioner, under its per-user advisory lock, at the
// ephemeral cap): lock the oldest leased worker of the owner that is RELEASABLE -- a lease set (live
// or expired), no non-terminal run, no open custody hold. SKIP LOCKED so a worker a claim or the
// reaper holds is passed over, not waited on. No row means nothing is releasable (provisioning is
// refused as today).
func (q *Queries) LockOldestReleasableLeasedEphemeralWorker(ctx context.Context, userID uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockOldestReleasableLeasedEphemeralWorker, userID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const lockReapableEphemeralWorkers = `-- name: LockReapableEphemeralWorkers :many
SELECT w.id FROM workers w
WHERE w.ephemeral
  AND NOT EXISTS (
      SELECT 1 FROM runs br
      WHERE br.worker_id = w.id
        AND br.status NOT IN ('completed', 'failed', 'cancelled')
  )
  -- PRD #1296 M4 (D3): the SAME custody skip as DeleteEphemeralWorkerForRun above — the
  -- reaper must never drop the last local source of a custody-held worker. The hold's
  -- live_worker_id FK is ON DELETE RESTRICT (a bypass fail-closes), and this predicate
  -- turns that into a graceful skip: the custody-release reconciler releases the hold once
  -- release is warranted, after which the next reap tick finds no open hold and proceeds.
  AND NOT EXISTS (
      SELECT 1 FROM recovery_custody_holds h
      WHERE h.live_worker_id = w.id AND h.state = 'open'
  )
  AND (
      (NOT EXISTS (
          SELECT 1 FROM runs r
          WHERE r.id = w.ephemeral_run_id
            AND r.status NOT IN ('completed', 'failed', 'cancelled')
      )
       -- PRD #2006: ...unless the worker holds a LIVE ephemeral lease (it finished that run and
       -- stays warm for a same-branch follow-up). Evaluated at clock_timestamp(), so a statement
       -- that waited on a lock never reaps through, or spares, a lease on a stale instant. A NULL
       -- or zero @ephemeral_lease, or no lease, reads false: today's selection exactly. The lease
       -- spares only a worker still LINKED to its served run (ephemeral_run_id IS NOT NULL): a
       -- worker whose run row was deleted (FK SET NULL) can never be re-bound by a claim, so it
       -- is an orphan and reaps on the next tick even with a live lease.
       AND NOT COALESCE(w.ephemeral_run_id IS NOT NULL
                        AND w.lease_since + $1::interval > clock_timestamp()
                        AND w.draining_since IS NULL, false))
      OR (w.online_since IS NULL AND w.created_at < $2)
      OR (w.online_since IS NOT NULL AND w.online_since < $2
          AND EXISTS (
              SELECT 1 FROM runs r
              WHERE r.id = w.ephemeral_run_id
                AND r.worker_id IS NOT NULL AND r.worker_id <> w.id
          ))
      OR EXISTS (
          SELECT 1 FROM runs r
          WHERE r.id = w.ephemeral_run_id
            AND (r.egress_profile_id IS NOT NULL) <> w.isolated_lane
      )
      OR (w.isolated_lane AND w.online_since IS NOT NULL
          AND NOT ('isolated_fetch_v1' = ANY(w.protocol_capabilities)))
  )
FOR UPDATE OF w SKIP LOCKED
`

type LockReapableEphemeralWorkersParams struct {
	EphemeralLease pgtype.Interval    `json:"ephemeral_lease"`
	DeadlineCutoff pgtype.Timestamptz `json:"deadline_cutoff"`
}

// Orphan/failure GC backstop (PRD #529 M5, Decision 6). DELETE every ephemeral worker
// that can no longer make progress. Busy-guarded so a worker holding ANY non-terminal
// run is never reaped mid-flight (defense-in-depth; M3's claim restriction means only the
// bound run ever points at it). The controller reaps the pod on its next poll (a hosted
// row's absence => teardown); the token row goes via ON DELETE CASCADE.
//
//	(a) no live bound run: NOT EXISTS a non-terminal run at ephemeral_run_id — covers a
//	    terminal owning run (the backstop for every terminal writer M4's SetState hook
//	    misses), an absent run, and an unlinked ephemeral_run_id (FK SET NULL).
//	(b) never booted past the provision deadline: online_since NULL and created_at old.
//	(c) idle-stolen: online past the deadline and the bound run is claimed by a SIBLING
//	    (worker_id set and != this worker), so this worker will never get work.
//	(d) lane mismatch (PRD #1906 M5): the worker's isolated_lane differs from whether its bound
//	    run is profile-bound, so ClaimRun's isolated-lane clause bars it from the run forever
//	    (and it holds the run's one uq_workers_ephemeral_run slot, which would starve the right
//	    trigger). No deadline: it can never make progress, so it goes on the next tick.
//	(e) lane worker without the lane protocol (PRD #1906 M5): an isolated_lane worker that is
//	    online (online_since set) but does not advertise 'isolated_fetch_v1' (an old image, or a
//	    fetcher env it could not load). ClaimRun's lane clause requires that capability, so it
//	    can never claim its bound run, yet it holds the run's uq_workers_ephemeral_run slot and
//	    one per-user slot. No deadline, like (d); the busy and custody guards above still apply.
//	    online_since stands in for "has registered" ONLY because the agent registers before it
//	    heartbeats: RegisterWorker writes protocol_capabilities in the same UPDATE that stamps
//	    online_since, but HeartbeatWorker also stamps online_since and never writes the
//	    capabilities, so a worker that heartbeated first would be reaped here with the column
//	    still at its '{}' default. agent/src/worker.ts awaits registerWithRetry before it starts
//	    heartbeatLoop; keep that order, or key this arm on a column only register writes. (The
//	    register nonce, snapshot_register_nonce, is not one: an older image sends none, and
//	    that is the image this arm exists to reap.)
//	(f) PRD #2006: arm (a) is spared while the worker's ephemeral lease is live at
//	    clock_timestamp(); the lease ending (expiry, drain, re-register) makes (a) true again.
//
// The reap is TWO statements in ONE transaction (store.ReapEphemeralWorkers): THIS one locks the
// selected rows FOR UPDATE SKIP LOCKED, then DeleteLockedEphemeralWorkers deletes them by id
// re-checking the SAME predicate on a fresh snapshot taken after the locks are held. A single
// DELETE is not enough: Postgres re-evaluates only the row's own columns after a lock wait, never
// the NOT EXISTS subqueries over runs, so a worker a concurrent claim or terminal report just
// changed could be deleted on a stale view. KEEP THE TWO PREDICATES BYTE-IDENTICAL.
func (q *Queries) LockReapableEphemeralWorkers(ctx context.Context, arg LockReapableEphemeralWorkersParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockReapableEphemeralWorkers, arg.EphemeralLease, arg.DeadlineCutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markHostedWorkerTokenDelivered = `-- name: MarkHostedWorkerTokenDelivered :execrows
UPDATE hosted_worker_tokens SET
    token_ciphertext = NULL,
    delivered_at     = now()
WHERE worker_id = $1
  AND worker_id IN (
      SELECT id FROM workers
      WHERE kind = 'hosted'
        AND token_hash = $2
  )
  AND (token_ciphertext IS NOT NULL OR delivered_at IS NULL)
`

type MarkHostedWorkerTokenDeliveredParams struct {
	WorkerID        uuid.UUID `json:"worker_id"`
	ProvedTokenHash []byte    `json:"proved_token_hash"`
}

// The delivery acknowledgement, driven by PROOF OF POSSESSION: the worker itself
// registered, and RequireWorker only resolved it by matching sha256(the token it
// presented) against workers.token_hash. So a pod is demonstrably holding the
// CURRENT token, and the api's sealed buffer has served its purpose and is
// destroyed (Decision 3's "never at rest in plaintext server-side"). The row
// survives with delivered_at stamped, which is what distinguishes a delivery from
// an expiry.
//
// It is NOT a controller assertion. A controller ack could only say "a Secret
// exists for W" without naming the token in it, so a rotation racing an in-flight
// ack destroyed the fresh plaintext undelivered and recorded the row as delivered
// steady-state while the pod 401'd forever on the old token. Registration cannot
// lie about the version: a pod holding T1 after a rotation to T2 fails auth
// outright.
//
// QUALIFYING THE DESTROY (@proved_token_hash) is what makes that true of the WRITE
// and not merely of the auth. Auth proves sha256(presented) = token_hash at T0, but
// a DB round trip (RegisterWorker) sits between T0 and this statement, so matching
// on worker_id alone would destroy "whatever is parked NOW": a rotation committing
// in that gap means a request that proved T1 destroys a freshly parked T2,
// undelivered, stamping delivered_at over it — the original defect, one layer down.
// Carrying the hash the caller ACTUALLY PROVED into the subquery makes a mid-flight
// rotation match zero rows, so T2 stays pending and the T2-bearing pod acks it
// properly when it registers.
//
// Load-bearing premise: token_hash and the parked ciphertext are always written by
// the SAME rotation transaction (an M2 requirement, pinned in the PRD), so "the
// hash I proved is still current" ≡ "the parked ciphertext is the token I proved".
// Callers MUST pass the hash from the AUTHENTICATED CONTEXT and never a
// post-register re-read of the row: RegisterWorker's RETURNING * would already
// carry the rotated value and defeat this predicate entirely.
//
// The (ciphertext IS NOT NULL OR delivered_at IS NULL) guard is for IDEMPOTENCE on
// re-registration — a pod rescheduled onto another node presents the same token
// again, and that must be a no-op, not a re-stamp. It admits exactly two states:
//   - pending  (ciphertext, no delivered_at) -> the real delivery
//   - expired  (neither)                     -> a late but genuine SELF-HEAL: the
//     Secret was written after all and the pod finally booted (a slow image pull,
//     an ImagePullBackOff that cleared), so the row is corrected to the truth
//     rather than left claiming a strand that a rotation would then "fix" for no
//     reason. Only a proof licenses this transition; a report never could. It
//     survives the hash predicate untouched — the prover still holds the current
//     token, it just booted late.
//
// and excludes the already-delivered state, which is where re-registration lands.
//
// Still scoped to kind='hosted': the handler already checks Kind, so this is
// defence in depth against a future caller that does not.
func (q *Queries) MarkHostedWorkerTokenDelivered(ctx context.Context, arg MarkHostedWorkerTokenDeliveredParams) (int64, error) {
	result, err := q.db.Exec(ctx, markHostedWorkerTokenDelivered, arg.WorkerID, arg.ProvedTokenHash)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rebindLeasedEphemeralWorker = `-- name: RebindLeasedEphemeralWorker :execrows
UPDATE workers
   SET ephemeral_run_id = $1::uuid,
       lease_since      = NULL,
       lease_repo_id    = NULL,
       lease_branch     = NULL,
       updated_at       = now()
 WHERE id = $2
   AND ephemeral
   AND ephemeral_run_id = $3::uuid
   AND lease_since IS NOT NULL
   AND draining_since IS NULL
   AND lease_since + $4::interval > clock_timestamp()
`

type RebindLeasedEphemeralWorkerParams struct {
	NewRunID       uuid.UUID       `json:"new_run_id"`
	WorkerID       uuid.UUID       `json:"worker_id"`
	OldRunID       uuid.UUID       `json:"old_run_id"`
	EphemeralLease pgtype.Interval `json:"ephemeral_lease"`
}

// PRD #2006: rebind a leased ephemeral worker to the run it just claimed through its lease, and end
// the lease (that run's own terminal starts a new one). Runs in the claim transaction, after
// ClaimRun, with the worker row already locked. It re-checks the lease against ITS OWN
// clock_timestamp(), never the admission instant the claim passed ClaimRun, so a lease that expired
// while the claim waited cannot rebind; the caller treats any count other than 1 as a refusal and
// rolls the claim back to its savepoint. Binding to a run another ephemeral worker already holds
// raises a unique violation on uq_workers_ephemeral_run, which the caller handles the same way.
func (q *Queries) RebindLeasedEphemeralWorker(ctx context.Context, arg RebindLeasedEphemeralWorkerParams) (int64, error) {
	result, err := q.db.Exec(ctx, rebindLeasedEphemeralWorker,
		arg.NewRunID,
		arg.WorkerID,
		arg.OldRunID,
		arg.EphemeralLease,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const uncordonHostedWorker = `-- name: UncordonHostedWorker :execrows
UPDATE workers
   -- Releasing the legacy cordon hands a pending drain to maintenance for cleanup.
   SET draining_since = CASE WHEN maintenance_phase IN ('requested','ready','stopping','recycling') THEN draining_since ELSE NULL END,
       maintenance_owns_drain = maintenance_phase IN ('requested','ready','stopping','recycling'),
       updated_at = now()
 WHERE id = $1 AND kind = 'hosted'
`

// Controller uncordon-write (issue #458): clear draining_since so a worker that was
// cordoned on drift but whose drift was then REVERTED (nothing to roll) resumes claiming.
// draining_since is otherwise cleared ONLY by RegisterWorker on an actual roll, so a
// reverted-drift worker would stay cordoned forever. Idempotent: NULL->NULL is harmless,
// so no `draining_since IS NOT NULL` guard — that keeps rows-affected=0 meaning
// unambiguously "no such hosted worker" (clean 404), not "already clear". kind='hosted'
// mirrors CordonHostedWorker: never touch an external worker.
func (q *Queries) UncordonHostedWorker(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, uncordonHostedWorker, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertHostedWorkerToken = `-- name: UpsertHostedWorkerToken :exec
INSERT INTO hosted_worker_tokens (worker_id, token_ciphertext, delivered_at, created_at)
VALUES ($1, $2, NULL, now())
ON CONFLICT (worker_id) DO UPDATE SET
    token_ciphertext = EXCLUDED.token_ciphertext,
    delivered_at     = NULL,
    created_at       = now()
`

type UpsertHostedWorkerTokenParams struct {
	WorkerID        uuid.UUID `json:"worker_id"`
	TokenCiphertext []byte    `json:"token_ciphertext"`
}

// Park a sealed join-token plaintext for the controller's next poll. Called by the
// provision path (M2) in the same transaction that inserts the worker row, so a
// worker can never exist with a token_hash but no pending plaintext to deliver.
//
// An UPSERT, not a plain INSERT, because this is also the ROTATION path (M2/M3):
// recovering a stranded worker mints a NEW token — new plaintext, new sha256 on
// the workers row, bumped hosted_generation — and re-parks it here, which must
// reset delivered_at so the fresh token reads as pending again. Old plaintext is
// never resurrected; no query in this file could, since the ciphertext is gone the
// moment it is delivered or expired.
func (q *Queries) UpsertHostedWorkerToken(ctx context.Context, arg UpsertHostedWorkerTokenParams) error {
	_, err := q.db.Exec(ctx, upsertHostedWorkerToken, arg.WorkerID, arg.TokenCiphertext)
	return err
}
